add('design','team-best-spender','チーム内の購入額首位',3,'実在する各チームで購入合計が最大のプレイヤーを1人返す。0円も候補、同額ならidが小さい人。team_id,player_id,total_amountをteam_id昇順。所属者なしは出さない。購入なしの購入合計は0。players.idとteams.idはそれぞれNULLでなく一意。buys.amountはNULLでない。対応するplayersがないbuysは集計しない。',['team_id','player_id','total_amount'],`-- Rank player totals only after aggregating purchase rows.
WITH totals AS(SELECT p.id,p.team_id,coalesce(SUM(b.amount),0) AS amount FROM players p JOIN teams t ON t.id=p.team_id LEFT JOIN buys b ON b.player_id=p.id GROUP BY p.id), ranked AS(SELECT *,row_number() OVER(PARTITION BY team_id ORDER BY amount DESC,id) AS n FROM totals)
SELECT team_id,id AS player_id,amount AS total_amount FROM ranked WHERE n=1 ORDER BY team_id;`,relationFixtures,t=>ordered(get(t,'teams'),'id').flatMap(team=>{const p=get(t,'players').filter(p=>p.team_id===team.id).sort((a,b)=>playerTotals(t).get(b.id)-playerTotals(t).get(a.id)||a.id-b.id);return p.length?[[team.id,p[0].id,playerTotals(t).get(p[0].id)]]:[];}));
add('design','co-purchased-items','同じ人が買った異なる品目',3,'同じプレイヤーが購入した異なるitemの組をitem_a<item_bとして重複なしで返す。item_a,item_b昇順。同じ品目の複数購入から自己組を作らない。playersに対応行がなくても、同じ非NULL player_idの購入は同一プレイヤー分として扱う。',['item_a','item_b'],`-- Deduplicate item pairs across all purchasing players.
SELECT DISTINCT a.item AS item_a,b.item AS item_b FROM buys a JOIN buys b ON a.player_id=b.player_id AND a.item<b.item ORDER BY item_a,item_b;`,relationFixtures,t=>{const pairs=new Set();for(const a of get(t,'buys'))for(const b of get(t,'buys'))if(a.player_id===b.player_id&&a.item<b.item)pairs.add(JSON.stringify([a.item,b.item]));return[...pairs].map(JSON.parse).sort((a,b)=>compare(a[0],b[0])||compare(a[1],b[1]));});
add('design','team-spending-share','チーム内の購入割合',3,'実在チーム所属者についてteam_id,player_id,shareを返す。share=個人購入額/チーム購入額を小数3桁に丸める。チーム合計0なら0。team_id,player_id昇順。players.idとteams.idはそれぞれNULLでなく一意。buys.amountはNULLでない。購入なしの個人購入額は0。対応するplayersがないbuysは集計しない。',['team_id','player_id','share'],`-- Divide aggregated player totals by the partition total.
WITH totals AS(SELECT p.id,p.team_id,coalesce(SUM(b.amount),0) AS amount FROM players p JOIN teams t ON t.id=p.team_id LEFT JOIN buys b ON b.player_id=p.id GROUP BY p.id)
SELECT team_id,id AS player_id,coalesce(round(amount*1.0/nullif(SUM(amount) OVER(PARTITION BY team_id),0),3),0) AS share FROM totals ORDER BY team_id,id;`,relationFixtures,t=>ordered(get(t,'players').filter(p=>get(t,'teams').some(x=>x.id===p.team_id)),'team_id','id').map(p=>{const total=sum(get(t,'players').filter(x=>x.team_id===p.team_id).map(x=>playerTotals(t).get(x.id)));return[p.team_id,p.id,total?Math.round(playerTotals(t).get(p.id)/total*1000)/1000:0];}));
const forestFixtures = [ [table('nodes','id INTEGER,parent_id INTEGER,name TEXT',[[1,null,'world'],[2,1,'town'],[3,2,'shop'],[4,1,'forest']])], [table('nodes','id INTEGER,parent_id INTEGER,name TEXT',[[9,5,'leaf'],[5,null,'root'],[7,null,'island']])], [table('nodes','id INTEGER,parent_id INTEGER,name TEXT',[])] ];
forestFixtures.push([table('nodes','id INTEGER,parent_id INTEGER,name TEXT',[[8,6,'leaf'],[3,null,'root'],[6,3,'branch'],[1,3,'other']])]);
const pathTo = (rows,node) => node.parent_id===null?node.name:pathTo(rows,rows.find(n=>n.id===node.parent_id))+'/'+node.name;
add('design','tree-paths','階層の絶対パス',4,'nodesは循環や孤児のない森。全ノードのid,pathをid昇順で返す。pathはルート名から各nameを/で結ぶ。nodes.idはNULLでなく一意。nameはNULLでない。',['id','path'],`-- Carry the full path through the recursive relation.
WITH RECURSIVE tree(id,path) AS(SELECT id,name FROM nodes WHERE parent_id IS NULL UNION ALL SELECT n.id,t.path||'/'||n.name FROM nodes n JOIN tree t ON n.parent_id=t.id)
SELECT id,path FROM tree ORDER BY id;`,forestFixtures,t=>{const n=get(t,'nodes');return ordered(n,'id').map(x=>[x.id,pathTo(n,x)]);});
add('design','tree-depths','複数ルートの深さ',4,'nodesは循環や孤児のない森。ルートの深さを0とし、全ノードのid,depthをid昇順で返す。nodes.idはNULLでなく一意。',['id','depth'],`-- Increment depth as the traversal descends one edge.
WITH RECURSIVE tree(id,depth) AS(SELECT id,0 FROM nodes WHERE parent_id IS NULL UNION ALL SELECT n.id,t.depth+1 FROM nodes n JOIN tree t ON n.parent_id=t.id)
SELECT id,depth FROM tree ORDER BY id;`,forestFixtures,t=>{const n=get(t,'nodes');return ordered(n,'id').map(x=>[x.id,pathTo(n,x).split('/').length-1]);});
add('design','descendant-counts','各ノードの子孫数',4,'nodesは循環や孤児のない森。全ノードのid,descendantsを返す。自分は含めず、直接・間接の子孫を数える。id昇順。nodes.idはNULLでなく一意。',['id','descendants'],`-- Build ancestor-descendant pairs, excluding self pairs.
WITH RECURSIVE links(ancestor,child) AS(SELECT parent_id,id FROM nodes WHERE parent_id IS NOT NULL UNION ALL SELECT l.ancestor,n.id FROM links l JOIN nodes n ON n.parent_id=l.child)
SELECT n.id,COUNT(l.child) AS descendants FROM nodes n LEFT JOIN links l ON l.ancestor=n.id GROUP BY n.id ORDER BY n.id;`,forestFixtures,t=>{const n=get(t,'nodes');return ordered(n,'id').map(x=>[x.id,n.filter(y=>{let p=y.parent_id;while(p!==null){if(p===x.id)return true;p=n.find(z=>z.id===p).parent_id;}return false;}).length]);});
const graphFixtures = [[table('edges','source INTEGER,target INTEGER',[[1,2],[2,3],[3,1],[3,4],[1,2]])],[table('edges','source INTEGER,target INTEGER',[[9,10],[20,21]])],[table('edges','source INTEGER,target INTEGER',[])]];
graphFixtures.push([table('edges','source INTEGER,target INTEGER',[[1,1],[2,3],[3,4],[2,3]])]);
add('design','transitive-reachability','循環を含む到達関係',4,'有向edgesから、1本以上の辺で到達できるsource,targetの組を重複なしで返す。循環により自分へ戻れる組も含む。source,target昇順。',['source','target'],`-- UNION removes repeated reachability pairs and terminates cycles.
WITH RECURSIVE reach(source,target) AS(SELECT source,target FROM edges UNION SELECT r.source,e.target FROM reach r JOIN edges e ON e.source=r.target)
SELECT source,target FROM reach ORDER BY source,target;`,graphFixtures,t=>{const e=get(t,'edges'),out=[];for(const s of[...new Set(e.map(x=>x.source))].sort((a,b)=>a-b)){const seen=new Set(),queue=e.filter(x=>x.source===s).map(x=>x.target);while(queue.length){const v=queue.shift();if(seen.has(v))continue;seen.add(v);queue.push(...e.filter(x=>x.source===v).map(x=>x.target));}for(const v of[...seen].sort((a,b)=>a-b))out.push([s,v]);}return out;});
const world = (rows, view) => [table('objects','id INTEGER,name TEXT,layer INTEGER,x INTEGER,y INTEGER,width INTEGER,height INTEGER,visible INTEGER,color INTEGER',rows),table('viewport','width INTEGER,height INTEGER,camera_x INTEGER,camera_y INTEGER',[view])];
const worldFixtures=[world([[1,'forest_gate',0,-2,1,4,3,1,0x3366CC],[2,'red_marker',1,8,2,5,2,1,0xFF0000],[3,'hidden_box',1,2,-3,3,2,0,0]], [10,8,0,0]),world([[3,'edge',2,8,8,0,3,1,0xFFFFFF],[1,'origin',1,2,1,1,1,1,0],[2,'outside',0,-5,2,2,2,1,0x00FF00]],[6,6,2,1]),world([],[10,8,0,0])];
worldFixtures.push(world([[10,'same_name',3,-2,-1,2,2,1,0x00000F],[2,'same_name',3,0,0,0,0,1,0x00000F],[7,'hidden',0,1,1,1,1,0,0]],[1,1,-1,-1]));
add('graphics','padded-object-identifiers','表示IDを0埋めする',1,'全objectsのid,labelをid昇順で返す。labelはobj-の後にidを最低3桁の0埋め10進で付ける。idは0以上100未満。',['id','label'],`-- Give object identifiers a fixed-width display form.
SELECT id,printf('obj-%03d',id) AS label FROM objects ORDER BY id;`,worldFixtures,t=>ordered(get(t,'objects'),'id').map(r=>[r.id,'obj-'+String(r.id).padStart(3,'0')]));
add('graphics','human-readable-object-names','内部名を表示名に変える',1,'全objectsのid,labelを返す。nameの_を全て空白に置き換える。id昇順。',['id','label'],`-- Keep the stored identifier but expose a readable label.
SELECT id,replace(name,'_',' ') AS label FROM objects ORDER BY id;`,worldFixtures,t=>ordered(get(t,'objects'),'id').map(r=>[r.id,r.name.replaceAll('_',' ')]));
add('graphics','rgb-css-labels','RGBを色文字列へ',1,'colorは0..0xFFFFFFのRGB整数。全objectsのid,color_textを返す。color_textは#に続く大文字16進6桁。id昇順。',['id','color_text'],`-- Render the packed color without losing leading zero bytes.
SELECT id,printf('#%06X',color) AS color_text FROM objects ORDER BY id;`,worldFixtures,t=>ordered(get(t,'objects'),'id').map(r=>[r.id,'#'+r.color.toString(16).toUpperCase().padStart(6,'0')]));
add('graphics','unpacked-color-channels','色を3チャンネルへ分ける',1,'全objectsについてid,red,green,blueをid昇順で返す。各成分は0..255。colorは0xRRGGBB。',['id','red','green','blue'],`-- Recover each byte from the packed RGB value.
SELECT id,(color>>16)&255 AS red,(color>>8)&255 AS green,color&255 AS blue FROM objects ORDER BY id;`,worldFixtures,t=>ordered(get(t,'objects'),'id').map(r=>[r.id,(r.color>>16)&255,(r.color>>8)&255,r.color&255]));
add('graphics','visible-command-list','描画指示の列を作る',2,'visible=1だけを選び、id,label,screen_x,screen_yを返す。labelはname、画面座標はワールド座標からカメラ座標を引く。layer昇順、id昇順。画面外も残す。viewportは1行。',['id','label','screen_x','screen_y'],`-- Build ordered draw commands relative to the current camera.
SELECT o.id,o.name AS label,o.x-v.camera_x AS screen_x,o.y-v.camera_y AS screen_y FROM objects o CROSS JOIN viewport v WHERE o.visible=1 ORDER BY o.layer,o.id;`,worldFixtures,t=>{const v=get(t,'viewport')[0];return ordered(get(t,'objects').filter(o=>o.visible===1),'layer','id').map(o=>[o.id,o.name,o.x-v.camera_x,o.y-v.camera_y]);});
add('graphics','clipped-render-rectangles','画面内の矩形だけを返す',2,'visible=1の矩形をカメラ相対へ変換し、画面[0,width)×[0,height)と交差する正の面積だけを返す。id,left_x,top_y,right_x,bottom_y。端に触れるだけは除外。id昇順。viewportは1行。 objectsのid,x,y,width,height,visibleとviewportの全列はNULLを含まない。objects.idは一意。objectsとviewportのwidth,heightは非負。',['id','left_x','top_y','right_x','bottom_y'],`-- Clip both rectangle edges and reject zero-area intersections.
WITH clipped AS(SELECT o.id,max(0,o.x-v.camera_x) AS left_x,max(0,o.y-v.camera_y) AS top_y,min(v.width,o.x-v.camera_x+o.width) AS right_x,min(v.height,o.y-v.camera_y+o.height) AS bottom_y FROM objects o CROSS JOIN viewport v WHERE o.visible=1)
SELECT id,left_x,top_y,right_x,bottom_y FROM clipped WHERE left_x<right_x AND top_y<bottom_y ORDER BY id;`,worldFixtures,t=>{const v=get(t,'viewport')[0];return ordered(get(t,'objects').filter(o=>o.visible===1),'id').map(o=>[o.id,Math.max(0,o.x-v.camera_x),Math.max(0,o.y-v.camera_y),Math.min(v.width,o.x-v.camera_x+o.width),Math.min(v.height,o.y-v.camera_y+o.height)]).filter(r=>r[1]<r[3]&&r[2]<r[4]);});
add('graphics','visible-layer-content','レイヤー内の名前一覧',2,'visible=1がある各layerについてlayer,namesを返す。namesはid昇順のnameをカンマ1文字で連結する。layer昇順。objects.idはNULLでなく一意。nameはNULLでない。',['layer','names'],`-- Define the input ordering before joining labels.
SELECT layer,group_concat(name,',') AS names FROM(SELECT layer,name FROM objects WHERE visible=1 ORDER BY layer,id) GROUP BY layer ORDER BY layer;`,worldFixtures,t=>[...groups(ordered(get(t,'objects').filter(o=>o.visible===1),'id'),'layer')].sort((a,b)=>a[0]-b[0]).map(([k,r])=>[k,r.map(o=>o.name).join(',')]));
add('graphics','origin-cell-density','原点を含むセルの密度',2,'visible=1の物体のカメラ相対原点を、4×4ピクセルのセルへ振り分ける。原点が画面外なら除外。cell_x,cell_y,object_countをcell_y,cell_x昇順で返す。矩形の面積ではなく原点を数える。viewportは1行。',['cell_x','cell_y','object_count'],`-- Count visible origins in nonnegative screen-space cells.
SELECT (o.x-v.camera_x)/4 AS cell_x,(o.y-v.camera_y)/4 AS cell_y,COUNT(*) AS object_count FROM objects o CROSS JOIN viewport v WHERE o.visible=1 AND o.x-v.camera_x>=0 AND o.x-v.camera_x<v.width AND o.y-v.camera_y>=0 AND o.y-v.camera_y<v.height GROUP BY cell_x,cell_y ORDER BY cell_y,cell_x;`,worldFixtures,t=>{const v=get(t,'viewport')[0],m=new Map();for(const o of get(t,'objects')){const x=o.x-v.camera_x,y=o.y-v.camera_y;if(o.visible!==1||x<0||y<0||x>=v.width||y>=v.height)continue;const key=JSON.stringify([Math.floor(x/4),Math.floor(y/4)]);m.set(key,(m.get(key)||0)+1);}return[...m].map(([k,n])=>[...JSON.parse(k),n]).sort((a,b)=>a[1]-b[1]||a[0]-b[0]);});
const motion=(rows,target)=>[table('frames','entity INTEGER,tick INTEGER,x INTEGER,label TEXT',rows),table('playhead','tick INTEGER',[[target]])];
const motionFixtures=[motion([[1,0,0,'idle'],[1,10,10,'walk'],[1,20,30,'walk'],[1,30,60,'idle'],[2,0,5,'stop'],[2,10,5,'stop']],15),motion([[7,25,0,null],[8,0,-5,'idle'],[7,5,10,'run']],15),motion([],0)];
motionFixtures.push(motion([[9,5,9,null]],0));
const tracks=t=>[...groups(get(t,'frames'),'entity')].sort((a,b)=>a[0]-b[0]).map(([k,r])=>[k,ordered(r,'tick')]);
add('graphics','frame-durations','各コマの保持時間',3,'各framesのentity,tick,durationを返す。durationは同じentityの次tickとの差、最終行は0。entity,tick昇順。tickはNULLでなく、entity内で一意。',['entity','tick','duration'],`-- Derive intervals without joining unrelated tracks.
SELECT entity,tick,coalesce(lead(tick) OVER(PARTITION BY entity ORDER BY tick)-tick,0) AS duration FROM frames ORDER BY entity,tick;`,motionFixtures,t=>tracks(t).flatMap(([e,r])=>r.map((x,i)=>[e,x.tick,i+1<r.length?r[i+1].tick-x.tick:0])));
add('graphics','sample-velocities','サンプル間の速度',3,'各framesについてentity,tick,velocityを返す。前のサンプルとの差x/差tickを小数2桁へ丸める。各entityの先頭はNULL。entity,tick昇順。tickとxはNULLでなく、tickはentity内で一意。',['entity','tick','velocity'],`-- Preserve missing velocity at the start of each track.
SELECT entity,tick,round((x-lag(x) OVER w)*1.0/(tick-lag(tick) OVER w),2) AS velocity FROM frames WINDOW w AS(PARTITION BY entity ORDER BY tick) ORDER BY entity,tick;`,motionFixtures,t=>tracks(t).flatMap(([e,r])=>r.map((x,i)=>[e,x.tick,i?Math.round((x.x-r[i-1].x)/(x.tick-r[i-1].tick)*100)/100:null])));
add('graphics','trailing-position-smoothing','直近3点の平滑化',3,'entity別に現在と直前2行までのxを平均して小数2桁へ丸め、entity,tick,smoothed_xを返す。先頭付近は存在する行だけ。entity,tick昇順。tickとxはNULLでなく、tickはentity内で一意。',['entity','tick','smoothed_x'],`-- Smooth by a bounded number of samples in each track.
SELECT entity,tick,round(AVG(x) OVER(PARTITION BY entity ORDER BY tick ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) AS smoothed_x FROM frames ORDER BY entity,tick;`,motionFixtures,t=>tracks(t).flatMap(([e,r])=>r.map((x,i)=>[e,x.tick,Math.round(sum(r.slice(Math.max(0,i-2),i+1).map(y=>y.x))/Math.min(3,i+1)*100)/100])));
add('graphics','cumulative-travel-distance','往復も含めた移動距離',3,'各entityの先頭から、隣接xの差の絶対値を累計する。entity,tick,distanceを返し先頭は0。entity,tick昇順。tickとxはNULLでなく、tickはentity内で一意。',['entity','tick','distance'],`-- Accumulate absolute movement instead of net displacement.
WITH deltas AS(SELECT entity,tick,abs(x-lag(x) OVER(PARTITION BY entity ORDER BY tick)) AS dx FROM frames)
SELECT entity,tick,SUM(coalesce(dx,0)) OVER(PARTITION BY entity ORDER BY tick ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS distance FROM deltas ORDER BY entity,tick;`,motionFixtures,t=>tracks(t).flatMap(([e,r])=>{let d=0;return r.map((x,i)=>[e,x.tick,d+=i?Math.abs(x.x-r[i-1].x):0]);}));
add('graphics','state-segment-identifiers','連続する表示状態の区切り',4,'各entityの先頭をsegment=1とし、直前行とlabelが変わるたび1増やす。NULL同士は同状態。entity,tick,segmentをentity,tick昇順で返す。tickはNULLでなく、entity内で一意。',['entity','tick','segment'],`-- Treat null labels as comparable states when finding boundaries.
WITH boundaries AS(SELECT entity,tick,CASE WHEN row_number() OVER w=1 OR label IS NOT lag(label) OVER w THEN 1 ELSE 0 END AS changed FROM frames WINDOW w AS(PARTITION BY entity ORDER BY tick))
SELECT entity,tick,SUM(changed) OVER(PARTITION BY entity ORDER BY tick ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS segment FROM boundaries ORDER BY entity,tick;`,motionFixtures,t=>tracks(t).flatMap(([e,r])=>{let n=0;return r.map((x,i)=>[e,x.tick,n+=i===0||x.label!==r[i-1].label?1:0]);}));
add('graphics','playhead-interpolation','再生位置の座標を補間する',4,'playheadは1行。各entityのxをplayhead.tickで線形補間して小数2桁へ丸め、entity,xをentity昇順で返す。範囲外は最初または最後のxへ固定。framesのentity,tick,xとplayhead.tickはNULLでなく、tickはentity内で一意。',['entity','x'],`-- Clamp outside the track and interpolate between surrounding samples.
WITH entities AS(SELECT DISTINCT entity FROM frames), bounds AS(SELECT e.entity,p.tick,coalesce((SELECT f.tick FROM frames f WHERE f.entity=e.entity AND f.tick<=p.tick ORDER BY f.tick DESC LIMIT 1),(SELECT MIN(tick) FROM frames f WHERE f.entity=e.entity)) AS low_tick,coalesce((SELECT f.tick FROM frames f WHERE f.entity=e.entity AND f.tick>=p.tick ORDER BY f.tick LIMIT 1),(SELECT MAX(tick) FROM frames f WHERE f.entity=e.entity)) AS high_tick FROM entities e CROSS JOIN playhead p)
SELECT b.entity,round(CASE WHEN b.low_tick=b.high_tick THEN a.x ELSE a.x+(z.x-a.x)*(b.tick-b.low_tick)*1.0/(b.high_tick-b.low_tick) END,2) AS x FROM bounds b JOIN frames a ON a.entity=b.entity AND a.tick=b.low_tick JOIN frames z ON z.entity=b.entity AND z.tick=b.high_tick ORDER BY b.entity;`,motionFixtures,t=>{const tick=get(t,'playhead')[0].tick;return tracks(t).map(([e,r])=>{const lo=r.filter(x=>x.tick<=tick).at(-1)||r[0],hi=r.find(x=>x.tick>=tick)||r.at(-1);const x=lo.tick===hi.tick?lo.x:lo.x+(hi.x-lo.x)*(tick-lo.tick)/(hi.tick-lo.tick);return[e,Math.round(x*100)/100];});});
add('graphics','distance-from-running-peak','過去の最大位置との差',4,'entity別の現在行までの最大xから、現在xを引いたretreatを求める。entity,tick,retreatをentity,tick昇順で返す。負のxも通常通り扱う。tickとxはNULLでなく、tickはentity内で一意。',['entity','tick','retreat'],`-- Keep the running peak inside each independent track.
SELECT entity,tick,MAX(x) OVER(PARTITION BY entity ORDER BY tick ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)-x AS retreat FROM frames ORDER BY entity,tick;`,motionFixtures,t=>tracks(t).flatMap(([e,r])=>{let peak=-Infinity;return r.map(x=>[e,x.tick,(peak=Math.max(peak,x.x))-x.x]);}));
add('graphics','track-summary-json','トラックをJSONへまとめる',4,'entityごとにtick昇順の[x,label]配列をJSON配列にまとめる。entity,samplesをentity昇順で返す。samplesはJSONテキスト。NULLのlabelも保持する。tickはNULLでなく、entity内で一意。',['entity','samples'],`-- Serialize ordered samples without dropping null fields.
SELECT entity,json_group_array(json_array(x,label)) AS samples FROM(SELECT entity,tick,x,label FROM frames ORDER BY entity,tick) GROUP BY entity ORDER BY entity;`,motionFixtures,t=>tracks(t).map(([e,r])=>[e,JSON.stringify(r.map(x=>[x.x,x.label]))]));

const accountFixture=(accounts,op,retired=[])=>[table('accounts','id INTEGER PRIMARY KEY,team TEXT,coins INTEGER',accounts),table('operation','source INTEGER,target INTEGER,amount INTEGER,bonus INTEGER', [op]),table('retired','id INTEGER',retired.map(x=>[x])),table('audit','id INTEGER,coins INTEGER',[]),table('stats','team TEXT,total INTEGER',[['obsolete',999]])];
const accountFixtures=[accountFixture([[1,'red',10],[2,'blue',0],[3,'red',-2]],[1,2,3,2],[3]),accountFixture([[2,'red',7],[1,'red',2],[3,'blue',0]],[1,2,5,1],[1,99]),accountFixture([],[1,2,1,2]),accountFixture([[1,'solo',8]],[1,1,3,0],[1])];
const accountRows=t=>ordered(get(t,'accounts'),'id').map(a=>[a.id,a.coins]);
const accountResult='SELECT id,coins FROM accounts ORDER BY id';
const mutate=(resultQuery,extra={})=>({mutation:true,resultQuery,...extra});
add('systems','grant-to-valid-balances','負債口座を除いて報酬を加算',1,'coinsが0以上の全accountsへoperation.bonusを加える。負数口座はそのまま。更新後id,coinsをid昇順で返す。operationは1行。',['id','coins'],`-- Do not reward balances currently marked as debt.
UPDATE accounts SET coins=coins+(SELECT bonus FROM operation) WHERE coins>=0;`,accountFixtures,t=>{const b=get(t,'operation')[0].bonus;return ordered(get(t,'accounts'),'id').map(a=>[a.id,a.coins+(a.coins>=0?b:0)]);},mutate(accountResult));
add('systems','guarded-account-purchase','残高内でだけ購入する',1,'operation.sourceの口座がありcoins>=amountならamountを引く。それ以外は全口座を変更しない。amountは非負。更新後id,coinsをid昇順で返す。operationは1行。',['id','coins'],`-- Apply a guarded debit as one database statement.
UPDATE accounts SET coins=coins-(SELECT amount FROM operation) WHERE id=(SELECT source FROM operation) AND coins>=(SELECT amount FROM operation);`,accountFixtures,t=>{const o=get(t,'operation')[0];return ordered(get(t,'accounts'),'id').map(a=>[a.id,a.coins-(a.id===o.source&&a.coins>=o.amount?o.amount:0)]);},mutate(accountResult));
add('systems','repair-negative-balances','負数だけを修正する',1,'accounts.coinsの負数を0へ修正し、他の値は維持する。更新後id,coinsをid昇順で返す。',['id','coins'],`-- Repair invalid negative values without touching valid balances.
UPDATE accounts SET coins=0 WHERE coins<0;`,accountFixtures,t=>accountRows(t).map(([id,c])=>[id,Math.max(0,c)]),mutate(accountResult));
