add('systems','remove-expired-cache','期限到達を含めてキャッシュ削除',1,'expiresがclock.now以下のcacheを削除する。NULLのexpiresは無期限として残す。更新後id,key,value,revision,expiresをid昇順で返す。clockは1行で、nowはNULLでない。',['id','key','value','revision','expires'],`-- Treat the exact expiry tick as expired.
DELETE FROM cache WHERE expires<=(SELECT now FROM clock);`,cacheFixtures,t=>ordered(get(t,'cache').filter(c=>c.expires===null||c.expires>get(t,'clock')[0].now),'id').map(c=>[c.id,c.key,c.value,c.revision,c.expires]),mutate(cacheResult));
