add('systems','version-guarded-snapshot-import','古いスナップショットを拒否する',3,'incomingのkeyは一意。snapshotsに未登録なら追加し、登録済みならincoming.revisionが厳密に大きい場合だけvalue,revisionを更新する。同版は既存値維持。key,value,revisionをkey昇順。snapshotsとincomingのkey,revisionはNULLでない。',['key','value','revision'],`-- Protect newer snapshots from equal or older imports.
INSERT INTO snapshots(key,value,revision) SELECT key,value,revision FROM incoming WHERE 1 ON CONFLICT(key) DO UPDATE SET value=excluded.value,revision=excluded.revision WHERE excluded.revision>snapshots.revision;`,upsertFixtures,t=>{const m=new Map(get(t,'snapshots').map(r=>[r.key,r]));for(const r of get(t,'incoming'))if(!m.has(r.key)||r.revision>m.get(r.key).revision)m.set(r.key,r);return[...m.values()].sort((a,b)=>compare(a.key,b.key)).map(r=>[r.key,r.value,r.revision]);},mutate('SELECT key,value,revision FROM snapshots ORDER BY key'));
add('systems','atomic-balance-transfer','成立する送金だけ反映する',3,'source,target両口座が存在し異なるIDで、source残高>=amountならamountをsourceからtargetへ送る。それ以外は全て不変。operationは1行、amount非負。最終id,coinsをid昇順。',['id','coins'],`-- Capture eligibility before either side of the transfer changes.
BEGIN;
CREATE TEMP TABLE transfer_plan AS SELECT o.* FROM operation o JOIN accounts a ON a.id=o.source JOIN accounts b ON b.id=o.target WHERE o.source<>o.target AND a.coins>=o.amount;
UPDATE accounts SET coins=coins-(SELECT amount FROM transfer_plan) WHERE id IN(SELECT source FROM transfer_plan);
UPDATE accounts SET coins=coins+(SELECT amount FROM transfer_plan) WHERE id IN(SELECT target FROM transfer_plan);
DROP TABLE transfer_plan;
COMMIT;`,accountFixtures,t=>{const o=get(t,'operation')[0],r=get(t,'accounts'),ok=o.source!==o.target&&r.some(a=>a.id===o.target)&&r.some(a=>a.id===o.source&&a.coins>=o.amount);return ordered(r,'id').map(a=>[a.id,a.coins+(ok?(a.id===o.source?-o.amount:a.id===o.target?o.amount:0):0)]);},mutate(accountResult));
